script:
test('work submitted exactly at the deadline keeps its raw score', function () {
  var actual = code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1700000000000, submittedAt: 1700000000000 });
  assert.deepEqual(actual, { periodsLate: 0, deduction: 0, score: 45 });
});

test('work submitted before the deadline keeps its raw score', function () {
  var actual = code.applyLatePenalty({ maxPoints: 50, rawScore: 30, deadline: 1700000000000, submittedAt: 1699999999999 });
  assert.deepEqual(actual, { periodsLate: 0, deduction: 0, score: 30 });
});

test('one millisecond late counts as one started period', function () {
  var actual = code.applyLatePenalty({ maxPoints: 50, rawScore: 30, deadline: 1700000000000, submittedAt: 1700000000001 });
  assert.deepEqual(actual, { periodsLate: 1, deduction: 5, score: 25 });
});

test('one hour late is one period and loses 10 percent of the maximum', function () {
  var actual = code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1700000000000, submittedAt: 1700003600000 });
  assert.deepEqual(actual, { periodsLate: 1, deduction: 5, score: 40 });
});

test('exactly 24 hours late is one period and not two', function () {
  var actual = code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1700000000000, submittedAt: 1700086400000 });
  assert.deepEqual(actual, { periodsLate: 1, deduction: 5, score: 40 });
});

test('one millisecond past 24 hours starts a second period', function () {
  var actual = code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1700000000000, submittedAt: 1700086400001 });
  assert.deepEqual(actual, { periodsLate: 2, deduction: 10, score: 35 });
});

test('49 hours late is three periods and loses 15 points', function () {
  var actual = code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1700000000000, submittedAt: 1700176400000 });
  assert.deepEqual(actual, { periodsLate: 3, deduction: 15, score: 30 });
});

test('exactly 72 hours late is three periods and not four', function () {
  var actual = code.applyLatePenalty({ maxPoints: 80, rawScore: 70, deadline: 1700000000000, submittedAt: 1700259200000 });
  assert.deepEqual(actual, { periodsLate: 3, deduction: 24, score: 46 });
});

test('exactly 120 hours late is five periods and not six', function () {
  var actual = code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1700000000000, submittedAt: 1700432000000 });
  assert.deepEqual(actual, { periodsLate: 5, deduction: 25, score: 20 });
});

test('one millisecond before 120 hours is still five periods', function () {
  var actual = code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1700000000000, submittedAt: 1700431999999 });
  assert.deepEqual(actual, { periodsLate: 5, deduction: 25, score: 20 });
});

test('one millisecond past 120 hours is six periods and scores 0', function () {
  var actual = code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1700000000000, submittedAt: 1700432000001 });
  assert.equal(actual.periodsLate, 6);
  assert.equal(actual.score, 0);
});

test('work more than five periods late scores 0', function () {
  var actual = code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1700000000000, submittedAt: 1700432600000 });
  assert.equal(actual.periodsLate, 6);
  assert.equal(actual.score, 0);
});

test('a penalty below zero is clamped to zero', function () {
  var actual = code.applyLatePenalty({ maxPoints: 50, rawScore: 10, deadline: 1700000000000, submittedAt: 1700176400000 });
  assert.deepEqual(actual, { periodsLate: 3, deduction: 15, score: 0 });
});

test('25 hours across a year boundary is two periods and not one calendar day', function () {
  var actual = code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1703984400000, submittedAt: 1704074400000 });
  assert.deepEqual(actual, { periodsLate: 2, deduction: 10, score: 35 });
});

test('25 hours across a leap day is two periods and not one calendar day', function () {
  var actual = code.countLatePeriods({ deadline: 1709168400000, submittedAt: 1709258400000 });
  assert.equal(actual, 2);
});

test('applyLatePenalty throws when the input has an unknown field', function () {
  assert.throws(function () {
    code.applyLatePenalty({ maxPoints: 50, rawScore: 45, deadline: 1700000000000, submittedAt: 1700000000000, bonus: 1 });
  }, /unknown field: bonus/);
});
